import { create } from 'zustand'
import { nanoid } from 'nanoid'
import type { Slide } from '@/types/slides'

export type FikaSlideGapPosition = 'before-first' | 'between' | 'after-last'

export interface FikaAiSlideInsertAnchor {
  /** Stable unique request id generated by Fika for correlation and cancellation. */
  requestId: string
  /** Semantic gap location at trigger time. */
  position: FikaSlideGapPosition
  /** Slide id immediately before the gap (`null` for `before-first` or empty deck). */
  afterSlideId: string | null
  /** Slide id immediately after the gap (`null` for `after-last` or empty deck). */
  beforeSlideId: string | null
  /** 1-based insertion index at trigger time (matches `slides.create` / `slides.insert`). */
  insertIndex: number
  /** Slide count at trigger time. */
  slideCount: number
  /** Active slide id at trigger time, if any. */
  currentSlideId: string | null
}

export interface FikaSlideInsertAnchorInput {
  position?: FikaSlideGapPosition
  afterSlideId?: string | null
  beforeSlideId?: string | null
  /** Optional 1-based fallback index if neither neighbor slide still exists. */
  fallbackIndex?: number
}

export interface FikaAiSlideInsertLabels {
  /** Primary action label, e.g. "Add slide with AI". */
  addWithAi?: string
  /** Accessible label for the gap before slide 1. */
  addWithAiBeforeFirst?: string
  /** Accessible label for a gap between slides (optional `{after}` / `{before}` 1-based placeholders). */
  addWithAiBetween?: string
  /** Accessible label for the gap after the last slide. */
  addWithAiAfterLast?: string
  /** Manual blank slide insertion button label at a gap. */
  addBlankSlide?: string
  /** Cancel label shown on pending skeleton slide / active AI insertion indicator. */
  cancel?: string
  /** Status text shown while a pending AI slide is generating. */
  generating?: string
}

export interface FikaAiSlideInsertCancelDetail {
  requestId: string
  slideId?: string
}

export interface FikaAiSlideInsertConfig {
  /** Show AI insert actions at slide gaps. Defaults to `true` when config object is supplied. */
  enabled?: boolean
  /** Disable AI insert triggers while keeping controls visible. */
  disabled?: boolean
  /** Host-localized labels; omitted entries fall back to Fika built-in i18n. */
  labels?: FikaAiSlideInsertLabels
  /** Optional direct callback invoked when user triggers AI insert at a gap. */
  onRequest?: (anchor: FikaAiSlideInsertAnchor) => void
  /** Optional direct callback invoked when user activates cancel on a pending AI skeleton slide. */
  onCancel?: (detail: FikaAiSlideInsertCancelDetail) => void
}

export type FikaAiSlideInsertInternalEvent =
  | { type: 'aiSlideInsertRequested'; data: FikaAiSlideInsertAnchor }
  | { type: 'aiSlideInsertCancelled'; data: FikaAiSlideInsertCancelDetail }

type AiSlideInsertEventListener = (event: FikaAiSlideInsertInternalEvent) => void

const eventListeners = new Set<AiSlideInsertEventListener>()

export const useAiSlideInsert = create<{ config: FikaAiSlideInsertConfig | null }>(() => ({
  config: null,
}))

export function setFikaAiSlideInsert(config?: FikaAiSlideInsertConfig | null): void {
  useAiSlideInsert.setState({ config: config ?? null })
}

export function getFikaAiSlideInsert(): FikaAiSlideInsertConfig | null {
  return useAiSlideInsert.getState().config
}

export function isFikaAiSlideInsertEnabled(config: FikaAiSlideInsertConfig | null): boolean {
  return !!config && config.enabled !== false
}

export function subscribeFikaAiSlideInsertEvents(listener: AiSlideInsertEventListener): () => void {
  eventListeners.add(listener)
  return () => {
    eventListeners.delete(listener)
  }
}

function dispatchInternalEvent(event: FikaAiSlideInsertInternalEvent): void {
  for (const listener of [...eventListeners]) {
    if (eventListeners.has(listener)) listener(event)
  }
}

export function createAiGapRequestId(): string {
  return `ai_gap_${nanoid(10)}`
}

/**
 * Build a stable gap anchor for the given 0-based splice position (`0..slides.length`).
 * `spliceIndex === 0` is `before-first`, `spliceIndex === slides.length` is `after-last`
 * (when slides exist), and intermediate indices are `between`.
 */
export function buildSlideGapAnchor(
  slides: readonly Pick<Slide, 'id'>[],
  spliceIndex: number,
  currentSlideId: string | null = null,
  requestId: string = createAiGapRequestId(),
): FikaAiSlideInsertAnchor {
  const count = slides.length
  const clamped = Math.max(0, Math.min(Math.trunc(spliceIndex), count))
  const position: FikaSlideGapPosition = count === 0 || clamped === 0
    ? 'before-first'
    : clamped >= count
      ? 'after-last'
      : 'between'
  const afterSlideId = clamped > 0 ? (slides[clamped - 1]?.id ?? null) : null
  const beforeSlideId = clamped < count ? (slides[clamped]?.id ?? null) : null
  return {
    requestId,
    position,
    afterSlideId,
    beforeSlideId,
    insertIndex: clamped + 1,
    slideCount: count,
    currentSlideId,
  }
}

/**
 * Resolve a stable 1-based insertion index (`1..slides.length + 1`) from an anchor
 * even after asynchronous edits, insertions, reorders, or neighbor deletions.
 */
export function resolveSlideGapInsertIndex(
  slides: readonly Pick<Slide, 'id'>[],
  anchor: FikaSlideInsertAnchorInput,
): number {
  const count = slides.length
  if (count === 0) return 1
  if (anchor.afterSlideId) {
    const afterIndex = slides.findIndex(slide => slide.id === anchor.afterSlideId)
    if (afterIndex >= 0) return afterIndex + 2
  }
  if (anchor.beforeSlideId) {
    const beforeIndex = slides.findIndex(slide => slide.id === anchor.beforeSlideId)
    if (beforeIndex >= 0) return beforeIndex + 1
  }
  if (anchor.position === 'before-first') return 1
  if (anchor.position === 'after-last') return count + 1
  if (typeof anchor.fallbackIndex === 'number' && Number.isFinite(anchor.fallbackIndex)) {
    return Math.max(1, Math.min(Math.trunc(anchor.fallbackIndex), count + 1))
  }
  return count + 1
}

export function emitFikaAiSlideInsertRequest(anchor: FikaAiSlideInsertAnchor): void {
  const config = getFikaAiSlideInsert()
  if (config?.disabled) return
  dispatchInternalEvent({ type: 'aiSlideInsertRequested', data: anchor })
  config?.onRequest?.(anchor)
}

export function emitFikaAiSlideInsertCancel(detail: FikaAiSlideInsertCancelDetail): void {
  const config = getFikaAiSlideInsert()
  dispatchInternalEvent({ type: 'aiSlideInsertCancelled', data: detail })
  config?.onCancel?.(detail)
}
